create extension if not exists "pgcrypto";
create table if not exists public.categories (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,parent_id uuid references public.categories(id) on delete set null,sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.articles (id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,excerpt text,body text,featured_image text,image_caption text,category_id uuid references public.categories(id) on delete set null,author_name text,location text,status text not null default 'draft' check (status in ('draft','review','scheduled','published','archived')),is_featured boolean not null default false,is_breaking boolean not null default false,seo_title text,meta_description text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists articles_status_published_at_idx on public.articles(status,published_at desc);
create index if not exists articles_category_id_idx on public.articles(category_id);
